select
id, user_id, title, num, progress, category, tags, language, content_type, index_name, score, compete_ratio,
is_default, parent_resume_id, create_time, update_time
from resume


        and id = #{id}


        and user_id = #{userId}


        and title = #{title}


        and num = #{num}


        and progress = #{progress}


        and category = #{category}


        and tags = #{tags}


        and language = #{language}


        and content_type = #{contentType}


        and index_name = #{indexName}


        and score = #{score}


        and compete_ratio = #{competeRatio}


        and is_default = #{isDefault}


        and parent_resume_id = #{parentResumeId}


        and create_time = #{createTime}


        and update_time = #{updateTime}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from resume


        and id = #{id}


        and user_id = #{userId}


        and title = #{title}


        and num = #{num}


        and progress = #{progress}


        and category = #{category}


        and tags = #{tags}


        and language = #{language}


